// ══════════════════════════════════════════════════════════════════════════════
//  MAXWARE · EXCEL          El formato de TODOS los Excel de TODOS los productos
//  ──────────────────────────────────────────────────────────────────────────
//  ESTE ARCHIVO ES LA FUENTE ÚNICA. No se copia y se retoca por producto: se
//  copia TAL CUAL. Si hay que cambiar el formato, se cambia ACÁ y se reparte.
//  [[norma-fuente-unica-datos]]
//
//  POR QUÉ EXISTE (Máximo, 07/08/2026): «usá Maxware para que todo Excel que
//  uses no tengas que estarlo cambiando». Cada producto tenía su propia copia
//  del helper, así que el formato se volvía a ajustar en cada uno — y el que
//  tenía apuro escribía XLSX.utils.json_to_sheet y salía un volcado de celdas
//  sin una sola propiedad de formato. [[norma-excel-al-cliente-siempre-profesional]]
//
//  QUÉ DA:
//    · Logo OFICIAL de Maxware incrustado (no uno dibujado a mano)
//      [[maxware-logo-oficial]]
//    · Banner con la marca del CLIENTE + «por Maxware C.A.» debajo
//    · Encabezados, autofiltro, panel congelado, bordes, anchos por contenido
//    · Filas vacías con borde: se lee como formulario, no como tabla cortada
//
//  CÓMO SE USA — dos caminos, el mismo resultado:
//
//    A) Por hoja, controlando todo:
//         var wb = MaxwareExcel.libro();
//         MaxwareExcel.hoja(wb, {name:'Piezas', subtitulo:'...', headers:[...],
//                                widths:[...], rows:[[...]], vacias:25});
//         await MaxwareExcel.descargar(wb, 'archivo.xlsx');
//
//    B) Con la misma forma que tenía XLSX (para convertir código viejo):
//         var wb = _xlNuevo();
//         _xlAgregar(wb, arregloDeObjetos, 'Nombre', 'qué es esta hoja');
//         await _xlGuardar(wb, 'archivo.xlsx');
//
//  DÓNDE CORRE: en el navegador (con ExcelJS cargado) y en Node
//  (require de este mismo archivo, con exceljs instalado). El mismo archivo en
//  los dos lados, para que una plantilla generada por un script salga IGUAL que
//  la que el cliente baja desde el sistema.
//
//  LA MARCA: sale de MaxwareExcel.marca(), que lee la config del clon. En una
//  instancia de cliente el banner dice la marca del CLIENTE; la línea «por
//  Maxware C.A.» va siempre debajo. Así el mismo archivo sirve para todos los
//  clones sin tocarle una línea. [[flotamax-clon-debrand-logo-checklist]]
// ══════════════════════════════════════════════════════════════════════════════
(function (raiz, definir) {
  var api = definir();
  if (typeof module === 'object' && module.exports) module.exports = api;   // Node
  raiz.MaxwareExcel = api;                                                  // navegador
  // Alias globales: dejan funcionar el código viejo sin tocar cada llamada.
  raiz._xlHoja      = api.hoja;
  raiz._xlDescargar = api.descargar;
  raiz._xlLibro     = api.libro_desde_hojas;
  raiz._xlNuevo     = api.nuevo;
  raiz._xlAgregar   = api.agregar;
  raiz._xlGuardar   = api.guardar;
  raiz._xlDeObjetos = api.de_objetos;
  raiz._xlBorde     = api.borde;
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';

  // Paleta de la casa. Un solo lugar.
  var NAVY = 'FF0B2E59', SLATE = 'FF334155', LIGHT = 'FFEEF2F7',
      EJEMPLO = 'FFF7FAFC', BORDE = 'FFCBD5E1';

  // Logo oficial, blanco sobre transparente para que se lea encima del navy.
  // Va INCRUSTADO a propósito: un Excel no puede depender de una URL — el
  // cliente lo abre sin internet, o lo reenvía, y la imagen tiene que estar.
  var LOGO_B64 = '';

  // La librería. En el navegador viene del <script> de ExcelJS. En Node hay que
  // INYECTARLA: `require('exceljs')` desde acá adentro se resolvería contra la
  // carpeta de ESTE archivo (maxware-tools/excel), donde no hay node_modules —
  // así que un script que sí tiene exceljs instalado igual se quedaba sin él.
  //   const MX = require('.../maxware-excel.js');
  //   MX.usar(require('exceljs'));
  var _EJS = null;
  function usar(lib) { _EJS = lib || null; return api_ref; }
  function ExcelJSdisponible() {
    if (_EJS) return _EJS;
    if (typeof ExcelJS !== 'undefined') return ExcelJS;                  // navegador
    if (typeof require === 'function') { try { return require('exceljs'); } catch (e) {} }
    return null;
  }

  function borde() {
    var t = { style: 'thin', color: { argb: BORDE } };
    return { top: t, left: t, bottom: t, right: t };
  }

  // La marca que va en el banner. En una instancia de cliente, la del CLIENTE.
  function marca() {
    try {
      if (typeof BTG_CONFIG !== 'undefined' && BTG_CONFIG)
        return String(BTG_CONFIG.empresa_marca || BTG_CONFIG.empresa_nombre || 'MAXWARE').toUpperCase();
    } catch (e) {}
    return 'MAXWARE';
  }

  // El renglón de abajo del banner: qué es el sistema. Lo pone el producto.
  function bajada() {
    try {
      if (typeof BTG_CONFIG !== 'undefined' && BTG_CONFIG && BTG_CONFIG.excel_bajada)
        return String(BTG_CONFIG.excel_bajada) + '  ·  por Maxware C.A.';
    } catch (e) {}
    return 'por Maxware C.A.';
  }

  function libro() {
    var EJS = ExcelJSdisponible();
    if (!EJS) return null;
    var wb = new EJS.Workbook();
    wb.creator = marca() + ' · Maxware C.A.';
    wb.created = new Date(0);   // fecha fija: dos corridas iguales dan el mismo archivo
    return wb;
  }

  // ── Una hoja con el formato de la casa ────────────────────────────────────
  // opts: {name, subtitulo, headers, widths, rows, ejemplos, vacias, banner}
  function hoja(wb, opts) {
    opts = opts || {};
    var headers = opts.headers || [], nCols = Math.max(1, headers.length);
    var ws = wb.addWorksheet(String(opts.name || 'Hoja').slice(0, 31),
                             { views: [{ state: 'frozen', ySplit: 4 }] });

    // Fila 1 — banner de marca. El logo va incrustado a la izquierda.
    ws.mergeCells(1, 1, 1, nCols);
    var b1 = ws.getCell(1, 1);
    b1.value = opts.banner || marca();
    b1.font = { bold: true, size: 20, color: { argb: 'FFFFFFFF' } };
    b1.alignment = { vertical: 'middle', horizontal: 'center' };
    b1.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: NAVY } };
    ws.getRow(1).height = 30;
    try {
      if (LOGO_B64 && LOGO_B64.indexOf('__') !== 0) {
        var idLogo = wb.addImage({ base64: LOGO_B64, extension: 'png' });
        // Flotante sobre la fila 1: no ocupa celda, así no estorba a los datos
        // ni se desarma si alguien inserta una columna.
        ws.addImage(idLogo, { tl: { col: 0.15, row: 0.18 },
                              ext: { width: 104, height: 22 },
                              editAs: 'oneCell' });
      }
    } catch (e) { /* sin logo, el banner de texto igual queda */ }

    // Fila 2 — quién hizo el sistema.
    ws.mergeCells(2, 1, 2, nCols);
    var b2 = ws.getCell(2, 1);
    b2.value = bajada();
    b2.font = { italic: true, size: 10, color: { argb: 'FFFFFFFF' } };
    b2.alignment = { vertical: 'middle', horizontal: 'center' };
    b2.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: SLATE } };
    ws.getRow(2).height = 16;

    // Fila 3 — QUÉ ES esta hoja. Sin esto, una plantilla de carga vuelve mal
    // llena y eso cuesta una semana.
    ws.mergeCells(3, 1, 3, nCols);
    var b3 = ws.getCell(3, 1);
    b3.value = opts.subtitulo || '';
    b3.font = { bold: true, size: 11, color: { argb: NAVY } };
    b3.alignment = { vertical: 'middle', horizontal: 'left', indent: 1 };
    b3.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LIGHT } };
    ws.getRow(3).height = 20;

    // Fila 4 — encabezados.
    headers.forEach(function (h, i) {
      var c = ws.getCell(4, i + 1);
      c.value = h;
      c.font = { bold: true, size: 10, color: { argb: 'FFFFFFFF' } };
      c.alignment = { vertical: 'middle', horizontal: 'center', wrapText: true };
      c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: NAVY } };
      c.border = borde();
    });
    ws.getRow(4).height = 24;
    ws.autoFilter = { from: { row: 4, column: 1 }, to: { row: 4, column: nCols } };

    // Datos. Los primeros `ejemplos` van en gris cursiva.
    var rows = opts.rows || [], ej = (opts.ejemplos == null ? 0 : opts.ejemplos);
    rows.forEach(function (r, ri) {
      for (var ci = 0; ci < nCols; ci++) {
        var c = ws.getCell(5 + ri, ci + 1);
        c.value = (r[ci] == null ? '' : r[ci]);
        c.border = borde();
        if (ri < ej) {
          c.font = { italic: true, size: 9, color: { argb: SLATE } };
          c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: EJEMPLO } };
        }
      }
    });

    // Filas vacías con borde: se lee como formulario que hay que llenar.
    var start = 5 + rows.length;
    for (var v = 0; v < (opts.vacias || 0); v++)
      for (var ci2 = 0; ci2 < nCols; ci2++) ws.getCell(start + v, ci2 + 1).border = borde();

    var widths = opts.widths || [];
    for (var w = 0; w < nCols; w++) ws.getColumn(w + 1).width = widths[w] || 16;
    return ws;
  }

  // ── Bajar el archivo (navegador) o escribirlo (Node) ──────────────────────
  async function descargar(wb, filename) {
    if (typeof document !== 'undefined' && typeof Blob !== 'undefined') {
      var buf = await wb.xlsx.writeBuffer();
      var blob = new Blob([buf], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      var a = document.createElement('a');
      a.href = URL.createObjectURL(blob); a.download = filename;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setTimeout(function () { URL.revokeObjectURL(a.href); }, 4000);
      return true;
    }
    await wb.xlsx.writeFile(filename);   // Node
    return true;
  }

  // ── Convierte [{col:valor}] al {headers, rows} que necesita `hoja` ────────
  // Recorre TODAS las filas para juntar las columnas: si una fila trae una que
  // la primera no tenía, igual sale. Con XLSX.utils.json_to_sheet se perdía en
  // silencio, porque ese arma los encabezados mirando solo la primera fila.
  function de_objetos(arr, anchos) {
    arr = arr || [];
    var headers = [], visto = {};
    arr.forEach(function (o) {
      Object.keys(o || {}).forEach(function (k) { if (!visto[k]) { visto[k] = 1; headers.push(k); } });
    });
    return {
      headers: headers,
      widths: headers.map(function (h, i) {
        return (anchos && anchos[i]) || Math.min(34, Math.max(11, String(h).length + 4));
      }),
      rows: arr.map(function (o) {
        return headers.map(function (h) { var v = (o || {})[h]; return v == null ? '' : v; });
      })
    };
  }

  // ── Un libro entero a partir de una lista de hojas ────────────────────────
  async function libro_desde_hojas(hojas, filename) {
    hojas = (hojas || []).filter(function (h) { return h && h.headers && h.headers.length; });
    if (!hojas.length) {
      if (typeof alert === 'function') alert('No hay datos para exportar.');
      return false;
    }
    var wb = libro();
    if (!wb) {
      // Sin ExcelJS: mejor plano que nada, pero que se SEPA que salió sin formato.
      // Un Excel feo es malo; uno que no se descarga es peor.
      try {
        if (typeof XLSX === 'undefined') throw new Error('no hay librería de Excel');
        var wbp = XLSX.utils.book_new();
        hojas.forEach(function (h) {
          XLSX.utils.book_append_sheet(wbp,
            XLSX.utils.aoa_to_sheet([h.headers].concat(h.rows || [])),
            String(h.name || 'Hoja').slice(0, 31));
        });
        XLSX.writeFile(wbp, filename);
        if (typeof mostrarToast === 'function')
          mostrarToast('⚠️ El Excel salió SIN formato (no cargó la librería). Recargá la página y volvé a exportarlo.', 'error');
      } catch (e) {
        if (typeof alert === 'function') alert('No se pudo generar el Excel: ' + ((e && e.message) || e));
        return false;
      }
      return false;
    }
    try {
      hojas.forEach(function (h) {
        hoja(wb, { name: h.name, subtitulo: h.subtitulo || '', headers: h.headers,
                   widths: h.widths || [], rows: h.rows || [],
                   ejemplos: (h.ejemplos == null ? 0 : h.ejemplos), vacias: h.vacias || 0 });
      });
      await descargar(wb, filename);
      return true;
    } catch (e) {
      if (typeof console !== 'undefined') console.error(e);
      if (typeof alert === 'function') alert('No se pudo generar el Excel: ' + ((e && e.message) || e));
      return false;
    }
  }

  // ── Misma forma que la API vieja de XLSX, para convertir código sin dolor ──
  function nuevo() { return { __hojas: [] }; }
  function agregar(wb, arr, nombre, subtitulo) {
    if (!wb || !wb.__hojas) return;
    if (!arr || !arr.length) return;          // hoja vacía: no se agrega
    var d = de_objetos(arr);
    wb.__hojas.push({ name: nombre, subtitulo: subtitulo || '',
                      headers: d.headers, widths: d.widths, rows: d.rows });
  }
  function guardar(wb, filename) { return libro_desde_hojas((wb && wb.__hojas) || [], filename); }

  var api_ref = { libro: libro, hoja: hoja, descargar: descargar, de_objetos: de_objetos,
           libro_desde_hojas: libro_desde_hojas, nuevo: nuevo, agregar: agregar,
           guardar: guardar, borde: borde, marca: marca, usar: usar,
           PALETA: { NAVY: NAVY, SLATE: SLATE, LIGHT: LIGHT, EJEMPLO: EJEMPLO, BORDE: BORDE } };
  return api_ref;
});
